function i(r,e){const t=Number(e)||0;return Number((Number(r||0)/(1+t/100)).toFixed(2))}function c(r,e){const t=Number(e)||0;return Number((Number(r||0)*(1+t/100)).toFixed(2))}function l(r,e,t,u){const n=Number(r||0);return t===u?Number(n.toFixed(2)):t==="tax_exclusive"&&u==="tax_inclusive"?c(n,e):i(n,e)}function b(r,e,t){const u=Number(r||0);if(t==="tax_inclusive"){const o=Number(u.toFixed(2));return{invoiceAmountExcl:i(o,e),totalIncl:o}}const n=Number(u.toFixed(2));return{invoiceAmountExcl:n,totalIncl:c(n,e)}}function x(r,e,t,u){const n=Number(r||0),o=Number(e),m=Number(t);if(!(n>0)||o===m||u==="tax_inclusive")return Number(n.toFixed(2));const s=c(n,o);return i(s,m)}export{x as a,l as c,c as i,b as r};
